<script setup>
import { Head, Link } from '@inertiajs/vue3';
import PortalLayout from '@/Layouts/PortalLayout.vue';
import CustomerNavigation from '@/Components/Customer/CustomerNavigation.vue';
defineProps({ payments: Array });
const money=(value,currency)=>new Intl.NumberFormat('en-NG',{style:'currency',currency}).format(Number(value));
</script>
<template><Head title="Payments"/><PortalLayout area="Customer Portal"><template #navigation><CustomerNavigation active="payments"/></template><div class="mb-6 flex flex-wrap items-end justify-between gap-4"><div><h1 class="text-3xl font-bold">Payments</h1><p class="mt-2 text-slate-600">Submit external payment evidence and follow finance verification.</p></div><Link :href="route('portal.payments.create')" class="form-button">Submit payment</Link></div><p v-if="$page.props.flash.success" class="success-message mb-5">{{ $page.props.flash.success }}</p><div class="space-y-4"><article v-for="payment in payments" :key="payment.uuid" class="flex flex-wrap items-center justify-between gap-4 rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200"><div><p class="font-bold text-[#0B3D6E]">{{ payment.number }}</p><p class="mt-1 text-sm text-slate-500">{{ payment.customer }} · {{ payment.reference }} · {{ payment.method.replaceAll('_',' ') }}</p><p v-if="payment.invoices.length" class="mt-1 text-sm">Allocated to {{ payment.invoices.join(', ') }}</p></div><div class="text-right"><p class="font-bold">{{ money(payment.amount,payment.currency) }}</p><p class="text-sm text-slate-500">{{ payment.date }}</p><span class="mt-1 inline-block text-xs font-bold uppercase text-cyan-800">{{ payment.status }}</span></div></article><p v-if="!payments.length" class="rounded-2xl bg-white p-10 text-center text-slate-500 ring-1 ring-slate-200">No payments have been submitted.</p></div></PortalLayout></template>
